const fs=require('fs');
const lines=fs.readFileSync('deliverables/plan.md','utf8').split(/\r?\n/);
let block=[], start=0;
function check(){
  if(block.length<2) return;
  const counts=block.map(l=>l.split('|').length-2);
  const uniq=[...new Set(counts)];
  if(uniq.length>1) console.log(`Table at line ${start} has inconsistent columns:`, counts);
}
lines.forEach((l,i)=>{
  if(l.trim().startsWith('|')){ if(!block.length) start=i+1; block.push(l.trim()); }
  else { check(); block=[]; }
});
check();
console.log('Table check complete.');
// Word count
console.log('Words:', fs.readFileSync('deliverables/plan.md','utf8').split(/\s+/).filter(Boolean).length);
